package com.example.product;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.web.bind.annotation.*;import java.util.Map;@SpringBootApplication @RestController public class ProductServiceApplication {public static void main(String[] a){SpringApplication.run(ProductServiceApplication.class,a);}@GetMapping("/products/{id}") public Map<String,Object> get(@PathVariable int id){return Map.of("id",id,"name","Laptop","price",55000);}}
